contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public {
        require(delay >= c.getMinDelay());
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        c.schedule(target, value, data, predecessor, salt, delay);
        bool pendingAfterSchedule = c.isOperationPending(id);
        bool doneAfterSchedule = c.isOperationDone(id);
        uint256 ts = c.getTimestamp(id);
        c.cancel(id);
        bool activeAfterCancel = c.isOperation(id);
        assert(
            pendingAfterSchedule &&
            !doneAfterSchedule &&
            ts > block.timestamp &&
            !activeAfterCancel
        );
    }
    receive() external payable {}
}

